INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','adjective-order','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"adjective-order","title":"Adjectives: position, order and noun phrases","level":"A2","order":21,"summary":"Describe nouns clearly and recognise the usual ordering of several adjectives.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Before a noun or after a linking verb","Usual adjective order","Linking verbs take descriptive adjectives","Restricted positions"],"rules":[{"title":"Before a noun or after a linking verb","explanation":"Many adjectives can come before a noun or after be, seem and other linking verbs. They describe a quality of the noun or subject. English adjectives do not normally change for plural number.","pattern":"a **quiet** room / The rooms are **quiet**.","commonMistakes":["Quiet rooms does not become quiets rooms. Number is normally marked on the noun."],"examples":["Describe the task’s quality: “The plan to prepare the visitor guide sounds **useful**.”","Describe the task’s quality: “The plan to restore the old portrait sounds **useful**.”"],"skill":"form"},{"title":"Usual adjective order","explanation":"A useful neutral order is opinion, size, age, shape, colour, origin, material, purpose, then noun. This is a strong tendency rather than an absolute law. Writers may change order for emphasis or grouping, and long strings are usually avoided.","pattern":"a **lovely small old wooden** box","commonMistakes":["Do not overload a noun with every category; two or three relevant details are normally clearer."],"examples":["Complete the plural noun phrase: “We need **clear** instructions to prepare the visitor guide.”","Complete the plural noun phrase: “We need **clear** instructions to restore the old portrait.”"],"skill":"meaning"},{"title":"Linking verbs take descriptive adjectives","explanation":"After a linking verb, an adjective describes the subject rather than the manner of an action. Compare The soup smells good with She smells the flower carefully. The verb’s role determines the modifier.","pattern":"The plan **sounds useful**.","commonMistakes":["Sounds usefully is not the normal way to say the plan itself seems useful."],"examples":["Choose the usual neutral adjective order for the box of supplies used to prepare the visitor guide. → **a small old wooden box**","Choose the usual neutral adjective order for the box of supplies used to restore the old portrait. → **a small old wooden box**"],"skill":"contrast"},{"title":"Restricted positions","explanation":"Some adjectives commonly prefer one position. Asleep and afraid are usually predicative: the child is asleep. Main and former usually come before nouns. Learn these restrictions with the individual adjective rather than assuming every adjective moves freely.","pattern":"the **main** road / The child is **asleep**.","commonMistakes":["An asleep child is less usual than a sleeping child; dictionary examples help with such lexical restrictions."],"examples":["Choose an adjective after be: “The assistant is **afraid** of preparing the visitor guide alone.”","Choose an adjective after be: “The assistant is **afraid** of restoring the old portrait alone.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-adjectives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Describe nouns clearly and recognise the usual ordering of several adjectives.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Before a noun or after a linking verb","explanation":"Many adjectives can come before a noun or after be, seem and other linking verbs. They describe a quality of the noun or subject. English adjectives do not normally change for plural number.","pattern":"a **quiet** room / The rooms are **quiet**.","commonMistakes":["Quiet rooms does not become quiets rooms. Number is normally marked on the noun."],"examples":["Describe the task’s quality: “The plan to prepare the visitor guide sounds **useful**.”","Describe the task’s quality: “The plan to restore the old portrait sounds **useful**.”"],"skill":"form","id":"adjective-order-foundation-1","domain":"modifiers","referenceIds":["bc-adjectives"],"readingVersion":"core-2026-09-v3"},{"title":"Usual adjective order","explanation":"A useful neutral order is opinion, size, age, shape, colour, origin, material, purpose, then noun. This is a strong tendency rather than an absolute law. Writers may change order for emphasis or grouping, and long strings are usually avoided.","pattern":"a **lovely small old wooden** box","commonMistakes":["Do not overload a noun with every category; two or three relevant details are normally clearer."],"examples":["Complete the plural noun phrase: “We need **clear** instructions to prepare the visitor guide.”","Complete the plural noun phrase: “We need **clear** instructions to restore the old portrait.”"],"skill":"meaning","id":"adjective-order-foundation-2","domain":"modifiers","referenceIds":["bc-adjectives"],"readingVersion":"core-2026-09-v3"},{"title":"Linking verbs take descriptive adjectives","explanation":"After a linking verb, an adjective describes the subject rather than the manner of an action. Compare The soup smells good with She smells the flower carefully. The verb’s role determines the modifier.","pattern":"The plan **sounds useful**.","commonMistakes":["Sounds usefully is not the normal way to say the plan itself seems useful."],"examples":["Choose the usual neutral adjective order for the box of supplies used to prepare the visitor guide. → **a small old wooden box**","Choose the usual neutral adjective order for the box of supplies used to restore the old portrait. → **a small old wooden box**"],"skill":"contrast","id":"adjective-order-foundation-3","domain":"modifiers","referenceIds":["bc-adjectives"],"readingVersion":"core-2026-09-v3"},{"title":"Restricted positions","explanation":"Some adjectives commonly prefer one position. Asleep and afraid are usually predicative: the child is asleep. Main and former usually come before nouns. Learn these restrictions with the individual adjective rather than assuming every adjective moves freely.","pattern":"the **main** road / The child is **asleep**.","commonMistakes":["An asleep child is less usual than a sleeping child; dictionary examples help with such lexical restrictions."],"examples":["Choose an adjective after be: “The assistant is **afraid** of preparing the visitor guide alone.”","Choose an adjective after be: “The assistant is **afraid** of restoring the old portrait alone.”"],"skill":"application","id":"adjective-order-foundation-4","domain":"modifiers","referenceIds":["bc-adjectives"],"readingVersion":"core-2026-09-v3"},{"domain":"modifiers","id":"adjective-complements","title":"Adjectives with complements and position restrictions","explanation":"Adjectives can take preposition phrases, infinitives or clauses as complements. Some normally occur after a linking verb rather than before a noun, while others strongly prefer attributive use. A complemented adjective phrase often follows its noun. Learn the adjective and the complement pattern together.","pattern":"**afraid of** dogs · **eager to** help","examples":["The people **responsible for the delay** apologised.","The child is **asleep**, but an **asleep child** is not the usual pattern."],"commonMistakes":["Related adjectives may have different patterns: interested in, keen on, eager to. Similar meaning does not guarantee identical complementation."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"modifiers","id":"postpositive-and-substantive-adjectives","title":"Adjectives after nouns and adjectives naming groups","explanation":"Adjectives follow indefinite pronouns such as something and anyone. They also occur after nouns in some fixed expressions or when a following complement makes the phrase long. The + adjective can refer to a group of people or an abstract category, but number and meaning depend on the expression.","pattern":"something **useful** · the **rich**","examples":["We need a room **large enough for everyone**.","**The elderly** may need additional support."],"commonMistakes":["The rich normally has plural human reference; the unknown can have abstract singular reference. Do not add an ordinary plural -s to rich in this group use."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"modifiers","id":"adjective-position-meaning","title":"When adjective position changes meaning","explanation":"Some adjectives change interpretation according to position. A concerned parent is worried, while the people concerned are those involved. Present, responsible and involved show similar contrasts in suitable contexts. Position is therefore part of meaning, not merely a stylistic option. Use a fuller phrase when a short adjective is ambiguous.","pattern":"the **people concerned** / **concerned people**","examples":["The **present manager** means the current manager.","The **members present** means the members who attended."],"commonMistakes":["The contrast depends on the particular adjective; it is not a general rule that every adjective changes meaning before and after its noun."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["a **quiet** room / The rooms are **quiet**.","a **lovely small old wooden** box","The plan **sounds useful**.","the **main** road / The child is **asleep**."],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["articles-place-names"],"readingReferenceIds":["bc-adjectives","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='adjective-order'
